import { it } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { cdkAnimationUse, stripComments } from '../testing/design-guards';
function walk(d: string): string[] { return readdirSync(d).flatMap((n) => { const p = join(d, n); return statSync(p).isDirectory() ? walk(p) : [p]; }); }
it('probe', () => {
  const files = walk(join(process.cwd(), 'src')).filter((p) => /\.(ts|html)$/.test(p) && !/\.spec\.ts$/.test(p));
  const rx = /\bcreateOverlayRef\s*\(|\boverlay\w*\s*\.\s*create\s*\(|\bdialog\w*\s*\.\s*open\s*\(|\bcdkConnectedOverlay\b/gi;
  for (const f of files) {
