    const rawCalls = (raw.match(rx) ?? []).length;
    const u = cdkAnimationUse(raw);
    const ratio = s.length / raw.length;
    if (rawCalls > 0 || ratio < 0.5) console.log('PROBE', f.replace(process.cwd(), ''), 'raw', rawCalls, 'stripped', u.calls, 'disabled', u.disabled, 'kept', ratio.toFixed(2));
  }
});
