    const ch = source[i]; const next = source[i + 1];
    if (ch === '"' || ch === "'" || ch === '`') { let j = i + 1; while (j < source.length && source[j] !== ch) j += source[j] === '\\' ? 2 : 1; out += source.slice(i, j + 1); i = j; }
    else if (ch === '/' && next === '/') { while (i < source.length && source[i] !== '\n') i++; out += '\n'; }
