// Pixel sampling through a canvas in the page (no image library needed).
async function pixels(page: Page, clip: { x: number; y: number; width: number; height: number }, scale: number) {
  const buf = await page.screenshot({ clip, scale: 'device' });
  return page.evaluate(async ({ b64 }) => {
    const img = new Image();
    img.src = 'data:image/png;base64,' + b64;
    await img.decode();
    const c = document.createElement('canvas');
    c.width = img.width; c.height = img.height;
    const ctx = c.getContext('2d')!;
    ctx.drawImage(img, 0, 0);
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    return { w: c.width, h: c.height, data: Array.from(d) };
