import { expect, test, type Page } from '$F/node_modules/@playwright/test';
import { field, storedValue } from '$F/e2e/support/form';
import { TODAY } from '$F/e2e/support/plans';
import { calendarDialog, dateButton, focusedName, activeOptionText } from '$F/e2e/support/design';

async function open(page: Page, c: 'co' | 'cl') {
  await page.clock.setFixedTime(TODAY);
  await page.goto('/' + c + '/datos');
  await expect(field(page, c === 'co' ? 'Placa' : 'Patente')).toBeVisible();
}

for (const gap of [0, 30, 100]) {
  for (const [label, key] of [['Tipo de documento', 'documentType'], ['Marca', 'make']] as const) {
    test('F06 Enter ArrowDown Enter gap ' + gap + ' ' + label, async ({ page }) => {
      const res: string[] = [];
      for (let run = 0; run < 3; run++) {
        await open(page, 'co');
        const c = field(page, label);
        await c.focus();
        await page.keyboard.press('Enter');
        if (gap) await page.waitForTimeout(gap);
        await page.keyboard.press('ArrowDown');
        if (gap) await page.waitForTimeout(gap);
        await page.keyboard.press('Enter');
        await page.waitForTimeout(300);
        res.push(String(await storedValue(page, key)) + '/' + (await c.getAttribute('aria-expanded')));
      }
      console.log('F06 race', label, 'gap', gap, res.join(' '));
    });
  }
}

test('F06 toggle with polling', async ({ page }) => {
  await open(page, 'co');
  const tipo = field(page, 'Tipo de documento');
  const seq: string[] = [];
  await tipo.click(); await page.waitForTimeout(200); seq.push(String(await tipo.getAttribute('aria-expanded')));
  await tipo.click(); await page.waitForTimeout(200); seq.push(String(await tipo.getAttribute('aria-expanded')));
  await tipo.click(); await page.waitForTimeout(200); seq.push(String(await tipo.getAttribute('aria-expanded')));
  await tipo.evaluate((el: HTMLElement) => el.click()); await page.waitForTimeout(200); seq.push(String(await tipo.getAttribute('aria-expanded')));
  await tipo.evaluate((el: HTMLElement) => el.click()); await page.waitForTimeout(200); seq.push(String(await tipo.getAttribute('aria-expanded')));
  console.log('F06 toggle', seq.join(' '));
});

test('F06 Ctrl+A / Meta+A caret (macOS)', async ({ page }) => {
  await open(page, 'co');
  const ciudad = field(page, 'Ciudad');
  await ciudad.focus();
  await page.keyboard.type('Bog');
  await page.waitForTimeout(200);
  const before = await ciudad.evaluate((el: HTMLInputElement) => [el.selectionStart, el.selectionEnd, el.value]);
  await page.keyboard.press('Control+A');
  await page.waitForTimeout(100);
  const ctrl = await ciudad.evaluate((el: HTMLInputElement) => [el.selectionStart, el.selectionEnd, el.value]);
  await page.keyboard.press('Meta+ArrowRight');
  await page.keyboard.press('Meta+A');
  await page.waitForTimeout(100);
  const meta = await ciudad.evaluate((el: HTMLInputElement) => [el.selectionStart, el.selectionEnd, el.value]);
  console.log('F06 selectall', JSON.stringify({ platform: process.platform, before, ctrl, meta }));
});

