  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  const s2 = { dialog: await dialog.count(), focus: await focusedName(page), stored: await storedValue(page, 'birthDate') };
  console.log('F08', JSON.stringify({ inList, s1, s2 }));
});
